package dev.unbox.unpvp;
import com.google.gson.*;
import com.mojang.authlib.GameProfile;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.entity.EntityOtherPlayerMP;
import net.minecraft.world.*;
/** Isolated visual and identity checks for the three existing logo variants. */
final class BadgeProbe {
 static int stage,ticks,checks;static volatile boolean ready;static JsonObject fixture;static EntityOtherPlayerMP crown,cash,ordinary;static int drawn;
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);checks++;System.out.println("[unpvp-badges] PASS "+message);}
 static void shot(String name){Minecraft mc=Minecraft.getMinecraft();java.io.File d=new java.io.File(mc.mcDataDir,"badge-probe");d.mkdirs();net.minecraft.util.ScreenShotHelper.saveScreenshot(d,name+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
 static EntityOtherPlayerMP player(int n,String name,double x){Minecraft mc=Minecraft.getMinecraft();EntityOtherPlayerMP p=new EntityOtherPlayerMP(mc.theWorld,new GameProfile(new UUID(0,n),name));p.setPosition(x,4,1);p.lastTickPosX=p.prevPosX=p.posX;p.lastTickPosY=p.prevPosY=p.posY;p.lastTickPosZ=p.prevPosZ=p.posZ;p.rotationYaw=p.prevRotationYaw=180;p.rotationYawHead=p.prevRotationYawHead=180;mc.theWorld.addEntityToWorld(-5000-n,p);return p;}
 static void tick(){Minecraft mc=Minecraft.getMinecraft();try{
  if(stage==0&&mc.currentScreen instanceof UiScreen){stage=1;mc.launchIntegratedServer("BadgeLab","Unbox Badge Lab",new WorldSettings(42,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT));return;}
  if(stage==1&&mc.thePlayer!=null){stage=2;mc.getIntegratedServer().addScheduledTask(()->{net.minecraft.world.WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);w.getGameRules().setOrCreateGameRule("doMobSpawning","false");w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.setWorldTime(6000);mc.getIntegratedServer().getConfigurationManager().getPlayerByUsername("UIPreview").setPositionAndUpdate(0,5,-7);ready=true;});}
  if(stage<2||!ready||mc.thePlayer==null)return;
  mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.limitFramerate=120;mc.thePlayer.capabilities.isFlying=true;mc.thePlayer.motionY=0;mc.thePlayer.rotationYaw=mc.thePlayer.prevRotationYaw=0;mc.thePlayer.rotationPitch=mc.thePlayer.prevRotationPitch=4;
  if(stage==2&&++ticks>40){stage=3;ticks=0;mc.displayGuiScreen(null);mc.setIngameNotInFocus();for(UiState.Module m:UiState.MODULES)UiState.set(m.id,false);UiState.set("nickname",true);UiState.set("nickname.value","Builder");crown=player(11,"CrownPlayer",-2);cash=player(12,"CashPlayer",0);ordinary=player(13,"OtherPlayer",2);
   fixture=new JsonObject();fixture.addProperty("connected",true);fixture.addProperty("updated",System.currentTimeMillis());JsonObject self=new JsonObject();self.addProperty("uuid",mc.thePlayer.getUniqueID().toString());self.addProperty("kind","microsoft");fixture.add("self",self);JsonArray badges=new JsonArray();badges.add(new JsonPrimitive(crown.getUniqueID().toString()));badges.add(new JsonPrimitive(cash.getUniqueID().toString()));fixture.add("badges",badges);JsonObject logos=new JsonObject();for(UUID id:new UUID[]{mc.thePlayer.getUniqueID(),crown.getUniqueID(),cash.getUniqueID()}){JsonObject logo=new JsonObject();logo.addProperty("id",id.equals(cash.getUniqueID())?NameBadges.LOGOS[2]:NameBadges.LOGOS[1]);logos.add(id.toString().replace("-",""),logo);}fixture.add("playerLogos",logos);JsonObject assets=new JsonObject();JsonArray items=new JsonArray();for(int i=1;i<3;i++){JsonObject item=new JsonObject();item.addProperty("id",NameBadges.LOGOS[i]);item.addProperty("name",i==1?"Creator Crown":"Fluttering Cash");item.addProperty("kind","logo");items.add(item);}assets.add("items",items);fixture.add("assets",assets);SocialBridge.write("unbox-social-view.json",fixture);return;
  }
  if(stage==3&&++ticks>50){check(NameBadges.known(crown.getUniqueID())&&!NameBadges.known(ordinary.getUniqueID()),"Only recognized remote players have badges");check(NameBadges.prefix(crown,crown.getDisplayName()).getUnformattedText().contains("\ue001"),"Crown equipment maps to remote nameplate");check(NameBadges.prefix(cash,cash.getDisplayName()).getUnformattedText().contains("\ue002"),"Cash equipment maps to remote nameplate");check(NameBadges.glyphs>0,"Actual world renderer draws custom badge glyphs");NameBadges.begin(mc.thePlayer);check(mc.fontRendererObj.getStringWidth("\ue000")==10,"Base logo participates in actual font measurement");check(mc.fontRendererObj.getStringWidth("\ue001")==14,"Crown participates in actual font measurement");NameBadges.end();check(NameBadges.glyph('\ue001')==-1,"Chat and other fonts cannot acquire badges outside name rendering");shot("remote-variants");mc.gameSettings.thirdPersonView=2;stage=4;ticks=0;drawn=NameBadges.glyphs;return;}
  if(stage==4&&++ticks>40){check(NameBadges.ownVisible(mc.thePlayer),"F5 enables own nameplate");check(mc.thePlayer.getName().equals("UIPreview")&&mc.thePlayer.getDisplayName().getUnformattedText().equals("Builder"),"Nickname preserves account identity");check(NameBadges.glyphs>drawn,"Third-person world continues rendering badges");shot("own-crown");mc.gameSettings.hideGUI=true;check(!NameBadges.ownVisible(mc.thePlayer),"F1 hides own nameplate");mc.gameSettings.hideGUI=false;mc.gameSettings.thirdPersonView=0;check(!NameBadges.ownVisible(mc.thePlayer),"First person hides own nameplate");
   JsonObject old=SocialBridge.copy(SocialBridge.view);SocialBridge.view.addProperty("updated",0);check(NameBadges.logo(mc.thePlayer.getUniqueID()).equals("badge"),"Expired equipment falls back to base logo");SocialBridge.view=old;SocialBridge.view.getAsJsonObject("self").addProperty("uuid",UUID.randomUUID().toString());check(NameBadges.logo(mc.thePlayer.getUniqueID()).equals("badge"),"Other account cannot provide equipment");SocialBridge.view=SocialBridge.copy(fixture);SkinsScreen s=new SkinsScreen(new HomeScreen(false));mc.displayGuiScreen(s);for(UiScreen.Control c:s.controls)if(c.label.equals("Logos")){c.key('\n',org.lwjgl.input.Keyboard.KEY_RETURN);break;}stage=5;ticks=0;return;}
  if(stage==5&&++ticks>40){shot("logo-library");SkinsScreen s=(SkinsScreen)mc.currentScreen;boolean found=false;for(UiScreen.Control c:s.controls)if(c.label.equals("Fluttering Cash")){found=c.active;c.key('\n',org.lwjgl.input.Keyboard.KEY_RETURN);break;}check(found,"Owned logo can be equipped from Appearance");stage=6;ticks=0;return;}
  if(stage==6&&++ticks>20){JsonObject c=SocialBridge.read("unbox-social-command.json");check(SocialBridge.text(c,"op").equals("equip-logo")&&SocialBridge.text(c,"id").equals(NameBadges.LOGOS[2]),"Equipment change uses existing launcher command");check(!NameBadges.fontScope(),"Name renderer releases font scope");check(org.lwjgl.opengl.GL11.glGetError()==0,"Badge rendering leaves no GL errors");System.out.println("[unpvp-badges] PASS checks="+checks);stage=7;mc.shutdown();}
 }catch(Exception e){throw new RuntimeException(e);}}
}
